@Timeout(30)
class LmdbSnapshotGrowthTest {

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void snapshotCopyDoesNotRaceWithMapGrowth(boolean compact, @TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc");
		try (TripleStore triples = new TripleStore(directory.resolve("triples").toFile(), config, null);
				var executor = Executors.newSingleThreadExecutor()) {
			triples.startTransaction();
			triples.storeTriple(1L, 2L, 3L, 0L, true);
			triples.commit();
			var barrier = triples.getTxnManager().lockManager();
			long stamp = barrier.writeLock();
			CountDownLatch copying = new CountDownLatch(1);
			var copy = executor.submit(() -> {
				copying.countDown();
				triples.copyEnvironment(directory.resolve("snapshot"), compact);
				return null;
			});
			try {
				assertTrue(copying.await(5, TimeUnit.SECONDS));
				assertThrows(TimeoutException.class, () -> copy.get(200, TimeUnit.MILLISECONDS),
						"the native copy must wait for the same exclusive barrier used by map resizing");
			} finally {
				barrier.unlockWrite(stamp);
			}
			copy.get(5, TimeUnit.SECONDS);
			try (TripleStore reopened = new TripleStore(directory.resolve("snapshot").toFile(), config, null);
					var txn = reopened.getTxnManager().createReadTxn();
					var records = reopened.getTriples(txn, -1, -1, -1, -1, true)) {
				assertArrayEquals(new long[] { 1L, 2L, 3L, 0L }, records.next());
				assertNull(records.next());
			}
		}
	}

	@Test
	void failedNativeCopyReleasesGrowthBarrier(@TempDir Path directory) throws Exception {
		try (TripleStore triples = new TripleStore(directory.resolve("triples").toFile(),
				new LmdbStoreConfig("spoc"), null)) {
			Path snapshot = Files.createDirectory(directory.resolve("snapshot"));
			Files.createFile(snapshot.resolve("data.mdb"));
			assertThrows(IOException.class, () -> triples.copyEnvironment(snapshot, true));
			var barrier = triples.getTxnManager().lockManager();
			long stamp = barrier.tryWriteLock();
			assertNotEquals(0L, stamp, "native copy failure must release the map-growth barrier");
			barrier.unlockWrite(stamp);
		}
	}

	@Test
	void snapshotDoesNotWaitForAnUnflushedSink(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile(), new LmdbStoreConfig("spoc"));
		store.init();
		try (var executor = Executors.newSingleThreadExecutor()) {
			LmdbSailStore backing = store.getBackingStore();
			try (var sink = backing.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				var values = SimpleValueFactory.getInstance();
				sink.approve(values.createIRI("urn:pending"), values.createIRI("urn:predicate"),
						values.createLiteral("uncommitted"), null);
				var snapshot = executor.submit(() -> backing.createOnlineSnapshot(directory.resolve("snapshot"),
						true, () -> {
						}));
				assertEquals(backing.getCurrentCommittedTxnId(), snapshot.get(2, TimeUnit.SECONDS),
						"copying committed data must not wait for an unflushed sink's retained writer lease");
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void snapshotWaitsForGrowthAdmissionBeforeCapturingBoundary(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile(), new LmdbStoreConfig("spoc"));
		store.init();
		try (var executor = Executors.newSingleThreadExecutor()) {
			LmdbSailStore backing = store.getBackingStore();
			var growth = backing.beginMapGrowthAttempt(new Object());
			CountDownLatch copying = new CountDownLatch(1);
			CountDownLatch captured = new CountDownLatch(1);
			var snapshot = executor.submit(() -> {
				copying.countDown();
				return backing.createOnlineSnapshot(directory.resolve("snapshot"), true, captured::countDown);
			});
			try {
				assertTrue(copying.await(5, TimeUnit.SECONDS));
				assertThrows(TimeoutException.class, () -> snapshot.get(200, TimeUnit.MILLISECONDS),
						"a snapshot must enter through growth admission before taking the sink lock");
				assertEquals(1L, captured.getCount(), "no boundary may be captured during the growth episode");
			} finally {
				growth.close();
			}
			assertEquals(backing.getCurrentCommittedTxnId(), snapshot.get(5, TimeUnit.SECONDS));
			assertEquals(0L, captured.getCount());
		} finally {
			store.shutDown();
		}
	}
}
